import asyncio
from fastmcp.server import FastMCP


server = FastMCP("simple-server")


@server.tool
def greet(name: str) -> str:
    """Greet someone by name."""
    return f"Hello, {name}!"


if __name__ == "__main__":
    asyncio.run(server.run_http_async(
        transport="streamable-http",
        host="127.0.0.1",
        port=8000
    ))
